function isStrictlyPalindromic(n) {
  const base = n - 2;
  const digits = [];
  let rest = n;
  while (rest > 0) {
    digits.push(rest % base);
    rest = Math.floor(rest / base);
  }
  let left = 0;
  let right = digits.length - 1;
  while (left < right) {
    if (digits[left] !== digits[right]) {
      return false;
    }
    left++;
    right--;
  }
  // Never reached for n >= 4: base n - 2 always breaks the palindrome.
  return false;
}

